INSERT INTO `backup_deleted_products_20260408_080627` VALUES ('500437142','ÁO CHẤM BI CÓ DÂY BUỘC','Áo cổ cao có dây buộc ở lưng và tay dài, bo thun co giãn. Có lót trong và họa tiết chấm bi.',1,'7','2026-03-29 08:00:42','2026-03-29 08:00:42'),('505408355','ÁO GI LÊ VẠT ĐẮP CHÉO KÈM THẮT LƯNG','Chiều cao người mẫu: 174 cm<br/><br/>Áo gi lê cổ ve lật, tay sát nách, có cầu vai. Có vạt đắp chéo, cài khuy phía trước và kèm thắt lưng cùng chất liệu.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('498527562','ÁO KHOÁC BIKER GIẢ DA LỘN DÁNG RỘNG','Chiều cao người mẫu: 175 cm | Cỡ: S<br/><br/>Áo khoác rộng kiểu biker cổ ve lật, dài tay, có đai ở vai. Có túi phía trước cài khóa kéo. Gấu áo có nếp gấp. Cài khóa kéo chéo ẩn và khuy bấm phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('512882010','ÁO KHOÁC BOMBER CẮT MAY SUÔNG VẢI COTTON','Áo khoác cắt may suông làm từ vải cotton dệt chéo. Cổ cao, dài tay, cổ tay bo và cài khuy. Có túi may viền hai bên hông. Gấu bo thun. Cài bằng khóa kéo ở phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('502738126','ÁO KHOÁC BOMBER DÁNG RỘNG','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng rộng làm từ vải kỹ thuật. Cổ cao, tay dài rộng. Có túi may viền hai bên hông. Bo thun co giãn. Khóa kéo hai chiều phía trước.<br/><br/>Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('502042430','ÁO KHOÁC BOMBER MỀM','Chiều cao người mẫu: 177 cm | Cỡ: S<br/><br/>Áo khoác bomber cổ tròn, dài tay. Viền co giãn. Túi may viền phía trước. Khóa kéo phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('495704013','ÁO KHOÁC CỔ CAO','Chiều cao người mẫu: 176 cm | Cỡ: S<br/><br/>Áo khoác cổ cao, dài tay, có đai cài ở vai. Túi đắp phía trước. Gấu điều chỉnh được bằng nút chặn. Cài phía trước bằng khuy bấm ẩn dưới vạt che.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('502158602','ÁO KHOÁC CỔ CAO DÁNG RỘNG','Chiều cao người mẫu: 177 cm | Cỡ: S<br/><br/>Áo khoác dáng rộng cổ cao có dây rút điều chỉnh. Tay dài, có đai và cài khuy. Có túi chìm ở đường may và túi có nắp, cài khuy phía trước. Cài bằng khóa kéo kim loại phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('504049103','ÁO KHOÁC CỔ CAO GẤU CHUN','Áo khoác cổ cao, dài tay. Có hai túi phía trước. Gấu áo bo thun co giãn. Cài khuy phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('502278936','ÁO KHOÁC CROPPED FIT CỔ NHUNG TĂM','Áo khoác dáng lửng, chất liệu cotton co giãn. Cổ ve lật bằng vải nhung tăm cùng màu. Dài tay, cổ tay cài khuy. Có túi cài khóa kéo ở ngực và hai bên hông. Gấu áo điều chỉnh được bằng đai cài bên hông. Hiệu ứng bạc màu. Cài khóa kéo ẩn dưới nẹp có khuy phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('499869108','ÁO KHOÁC DA HIỆU ỨNG CỔ ĐIỂN','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng rộng làm bằng da có hiệu ứng cổ điển. Cổ ve lật và dài tay. Túi đắp có nắp ở hông. Chi tiết túi bên trong. Gấu áo bo gân co giãn. Cài khóa kéo phía trước. <br/><br/>Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('496063614','ÁO KHOÁC DA LỘN','Chiều cao người mẫu: 185 cm | Cỡ: M<br/><br/>Áo khoác dáng lửng làm từ da lộn. Cổ ve lật có khuy và dài tay, cổ tay có khuy cài. Có túi may viền hai bên hông và một túi ở lớp vải lót bên trong. Cài bằng hàng khuy phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('500817344','ÁO KHOÁC DA LỘN DÁNG REGULAR FIT','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng regular fit bằng da lộn. Cổ cao và dài tay. Túi may viền hai bên hông và một túi ở lớp vải lót bên trong. Gấu áo bo chun. Cài bằng khóa kéo ở phía trước.<br/><br/>Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('499773052','ÁO KHOÁC DA LỘN HIỆU ỨNG CỔ ĐIỂN','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng suông làm từ da lộn hiệu ứng cổ điển. Cổ ve lật, dài tay. Có túi vuông ở mặt trước. Cài khuy phía trước. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('506605946','ÁO KHOÁC DÁNG CROPPED CÓ KHÓA KÉO','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng lửng, làm bằng vải cotton. Cổ cao, tay dài, bo ở cổ tay có cài khuy. Có túi hai bên ở đường may. Vải hiệu ứng bạc màu. Cài phía trước bằng khóa kéo.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('507714246','ÁO KHOÁC DÁNG RỘNG CÀI KHUY BẤM VÀ CỌC ÁO','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng rộng làm từ vải cotton dệt chéo. Bên trong chần bông nhẹ. Cổ ve lật và tay dài bo cổ tay cài khuy. Túi vuông ở hai bên hông. Hiệu ứng giặt mài. Cài phía trước bằng khóa kéo ẩn bên dưới nẹp có khuy bấm và cọc áo kim loại.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('498006613','ÁO KHOÁC DÁNG RỘNG CHẦN CHỈ NỔI KHÁC MÀU','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng rộng làm từ vải cotton dệt chéo. Cổ ve lật, dài tay, cổ tay bo và cài khuy. Có túi kangaroo phía trước. Toàn thân chần chỉ nổi khác màu. Hiệu ứng phai màu. Cài bằng khóa kéo ở phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('506606772','ÁO KHOÁC DÁNG RỘNG VẢI CANVAS COTTON','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng rộng làm từ vải cotton dệt canvas. Cổ cao và dài tay, cổ tay cài khuy. Có túi hộp có nắp ở phía trước. Hiệu ứng wash. Cài bằng khóa kéo ẩn dưới nẹp có khóa kéo ở phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('507662945','ÁO KHOÁC DÁNG RỘNG VẢI COTTON','Áo khoác dáng rộng vải cotton. Cổ cao cài khuy. Dài tay, cổ tay cài khuy. Có túi may viền phía trước. Hiệu ứng vải mài. Cài bằng khóa kéo ẩn dưới nẹp có khuy bấm phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('499204213','ÁO KHOÁC DÁNG RỘNG VẢI DỆT PHỐI VIỀN TƯƠNG PHẢN','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác vải dệt họa tiết không đều, dáng rộng. Cổ cao, dài tay. Phối viền tương phản phía trước và sau. Túi cài khóa kéo phía trước. Bo thun co giãn. Cài bằng khóa kéo ở phía trước.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('508636661','ÁO KHOÁC DÁNG THƯỜNG 100% LEN','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng thường làm từ vải len (trừ lớp lót bên trong). Cổ ve lật và dài tay. Túi may viền ở hông. Gấu bo thun co giãn. Cài phía trước bằng khóa kéo. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('495697357','ÁO KHOÁC DENIM Z1975','Chiều cao người mẫu: 176 cm<br/><br/>Áo khoác cổ ve lật, dài tay. Có hai túi đáp phía trước. Cài bằng khuy kim loại phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('519858821','ÁO KHOÁC DENIM ZW COLLECTION','ZARA WOMAN COLLECTION<br/><br/>Áo khoác may bằng vải cotton. Cổ ve lật, tay dài. Túi có nắp phía trước. Hiệu ứng wash. Cài phía trước bằng khuy giấu dưới nắp che.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('511956894','ÁO KHOÁC GIẢ DA','Chiều cao người mẫu: 180 cm<br/><br/>Áo khoác cổ cao. Dài tay, bo cổ tay, may con đỉa ở vai. Có túi hai bên. Bên trong lót vải khác chất liệu. Cài phía trước bằng khóa kéo ẩn dưới vạt che cài khuy bấm.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('508053634','ÁO KHOÁC GIẢ DA CÓ THẮT LƯNG ZW COLLECTION','Chiều cao người mẫu: 178 cm<br/><br/>ZARA WOMAN COLLECTION<br/><br/>Áo khoác làm từ vải chính. Cổ cao và dài tay. Có dây thắt lưng điều chỉnh được. Lớp lót bên trong.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('498167052','ÁO KHOÁC GIẢ DA LỘN','Áo khoác chất liệu giả da lộn. Cổ ve lật. Dài tay, vai trễ. Túi ẩn hai bên đường may. Lót trong bằng vải khác. Gấu áo có thun co giãn bên trong.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('503041165','ÁO KHOÁC GIẢ DA LỘN','Chiều cao người mẫu: 173 cm | Cỡ: S<br/><br/>Áo khoác cổ cao, dài tay. Có hai túi phía trước, túi may viền. Cài phía trước bằng khóa kéo ẩn và khuy bấm.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('496094473','ÁO KHOÁC GIẢ DA LỘN CÓ DÂY ĐAI','Áo khoác chất liệu giả da lộn. Cổ đứng và dài tay có dây đai ở vai. Túi hộp có nắp phía trước. Cài khóa kéo và khuy bấm ẩn phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('503718891','ÁO KHOÁC HIỆU ỨNG BẠC MÀU','Chiều cao người mẫu: 176 cm | Cỡ: S<br/><br/>Áo khoác cổ cao, dài tay, cổ tay bo. Túi viền phía trước. Lót trong phối. Cài phía trước bằng khoá kéo và khuy bấm.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('507274223','ÁO KHOÁC KHÓA KÉO RÁP BÈO','Áo khoác cổ cao, có mũ điều chỉnh được bằng dây rút. Dài tay, viền nhún bèo co giãn ở cổ tay. Gấu nhún bèo điều chỉnh được bằng dây buộc. Túi viền ở phía trước. Cài phía trước bằng khóa kéo.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('502145185','ÁO KHOÁC KỸ THUẬT CHẦN BÔNG','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng ôm vừa vặn làm từ vải kỹ thuật pha cotton, bên trong chần bông nhẹ. Cổ ve lật, dài tay. Có túi may viền hai bên hông và một túi nhỏ bên trong. Gấu áo bo thun co giãn. Cài bằng khóa kéo ở phía trước. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('505341375','ÁO KHOÁC KỸ THUẬT CHẦN BÔNG CÓ TÚI','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng rộng làm bằng vải kỹ thuật, chần bông bên trong. Cổ cao và dài tay, cổ tay có khuy bấm ẩn. Có túi đáp phía trước có nắp. Có túi bên trong. Cạp quần có dây rút bên trong để điều chỉnh. Cài phía trước bằng khóa kéo ẩn dưới nẹp. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('503735733','ÁO KHOÁC OVERSIZE CÓ ĐƯỜNG MAY NỔI','Áo khoác cổ cao. Dài tay, vai rủ. Có túi viền phía trước. Chi tiết các đường may nổi phối hợp. Gấu áo có dây rút điều chỉnh được. Cài phía trước bằng khuy bấm.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('497813102','ÁO KHOÁC PARKA VẢI KỸ THUẬT KÈM ÁO GHI LÊ THÁO RỜI','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác parka dáng rộng làm từ vải kỹ thuật. Cổ cao điều chỉnh được bằng dây rút. Mũ trùm đầu có thể tháo rời bằng khóa kéo. Dài tay, cổ tay có khuy bấm. Túi có nắp ở ngực và túi đắp có nắp ở hông. Eo điều chỉnh được bằng dây rút bên trong. Gấu áo có xẻ tà ở giữa lưng. Cài phía trước bằng khóa kéo ẩn dưới vạt che có khuy bấm.<br/><br/>Áo ghi lê bên trong làm từ vải chần bông nhẹ. Có thể tháo rời bằng khuy. Cổ chữ V và sát nách. Chi tiết túi đắp ở hông.<br/><br/>Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('495686151','ÁO KHOÁC TAY BỒNG CÓ KHÓA KÉO','Chiều cao người mẫu: 182 cm<br/><br/>Áo khoác cổ ve lật, dài tay. Túi may viền đôi phía trước. Viền co giãn và tay bồng. Cài khóa kéo phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('502539889','ÁO KHOÁC TÚI ĐÁP','Chiều cao người mẫu: 176 cm<br/><br/>Áo khoác cổ ve lật, dài tay. Có túi đáp phía trước. Cài khuy phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('499180631','ÁO KHOÁC VẢI KỸ THUẬT BOXY FIT CHỐNG THẤM NƯỚC','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng boxy fit làm từ vải kỹ thuật có khả năng chống thấm nước khi tiếp xúc. Vải giúp giữ khô ráo trong thời gian ngắn tiếp xúc. Cổ cao và dài tay. Túi phía trước có khóa kéo. Bo thun co giãn. Cài phía trước bằng khóa kéo.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('498880192','ÁO KHOÁC VẢI KỸ THUẬT KÈM ÁO GHI LÊ THÁO RỜI ĐƯỢC','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng ôm vừa vặn, làm bằng vải kỹ thuật. Cổ cao, cài khuy, dài tay. Có túi đắp nắp ở hông. Có túi bên trong. Bo viền bằng vải gân co giãn. Cài phía trước bằng khóa kéo ẩn dưới vạt có khuy bấm. Áo ghi lê chần bông bên trong có thể tháo rời bằng khuy. Cổ chữ V và sát nách. Có túi bên trong. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-29 08:00:41','2026-03-29 08:00:41'),('509027857','ÁO KHOÁC VẢI THÔ','Áo khoác cổ tròn, dài tay, có đệm vai. Có hai túi hộp có nắp phía trước. Cài khuy phía trước.',1,'6','2026-03-29 08:00:42','2026-03-29 08:00:42'),('499871370','ÁO KHOÁC VẢI WASH PHỐI CỔ','Chiều cao người mẫu: 186 cm | Cỡ: L