/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES ('021ae64b-d3a0-4221-a59b-9c3e358a1dba','QUẦN VÁY GẤU PHỐI REN','Chiều cao người mẫu: 178 cm<br/><br/>Quần giả chân váy cạp cao. Gấu hoàn thiện bằng ren. Có lớp lót bên trong. Cài khóa kéo ẩn ở đường may bên hông.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('0267cd4e-04bd-4d96-a084-10f8ef61a98e','ÁO KHOÁC HIỆU ỨNG BẠC MÀU','Chiều cao người mẫu: 176 cm | Cỡ: S<br/><br/>Áo khoác cổ cao, dài tay, cổ tay bo. Túi viền phía trước. Lót trong phối. Cài phía trước bằng khoá kéo và khuy bấm.',1,'5','2026-03-26 13:54:58','2026-03-26 13:54:58'),('02a6ad8f-6f1e-45cd-b4ca-beab32a99668','ÁO KHOÁC DENIM Z1975','Chiều cao người mẫu: 176 cm<br/><br/>Áo khoác cổ ve lật, dài tay. Có hai túi đáp phía trước. Cài bằng khuy kim loại phía trước.',1,'5','2026-03-26 13:54:57','2026-03-26 13:54:57'),('04a26a6e-dc9c-4085-9328-1171bb3e22f1','ÁO VẢI RŨ TAY BỒNG','Chiều cao người mẫu: 177 cm | Cỡ: S<br/><br/>Áo cổ tròn, có đường may nhún, tay lỡ. Viền tay bồng, có dây thun bên trong. Cài khuy phía trước.',1,'6','2026-03-26 13:54:58','2026-03-26 13:54:58'),('04c1e103-a4bb-476f-aaa6-902ddec3ba4d','ÁO SƠ MI KẺ CA RÔ PHA LEN THUỘC BỘ SƯU TẬP ORIGINS','Áo sơ mi dáng regular fit, được làm từ vải pha len và cotton. Cổ ve lật, dài tay, cổ tay cài khuy. Cài khuy phía trước. Bộ sưu tập đặc biệt Origins.',1,'3','2026-03-26 13:54:57','2026-03-26 13:54:57'),('0500ce34-5530-4f23-b27e-8440be0a6b01','ÁO SƠ MI DÁNG REGULAR FIT','Chiều cao người mẫu: 188 cm | Cỡ: L<br/><br/>Áo sơ mi dáng regular fit làm từ vải hạn chế nhăn sau khi giặt. Cổ Ý mở, tay dài, cổ tay bo có nút. Cài khuy phía trước.',1,'3','2026-03-26 13:54:57','2026-03-26 13:54:57'),('06d7885f-9531-42f5-adb2-6474f1ac30c3','QUẦN BALLOON FIT XẾP LI','Chiều cao người mẫu: 185 cm<br/><br/>Quần dáng balloon fit được làm từ vải cotton và vải lanh chưa giặt. Điều này tạo cảm giác cứng khi mới mặc nhưng sẽ mềm dần theo thời gian sử dụng.<br/><br/>Dáng quần rộng từ hông và hơi bó ở gấu quần. Cạp vừa.<br/><br/>Cạp quần có chi tiết xếp li phía trước. Túi phía trước và túi may viền phía sau. Cài phía trước bằng khóa kéo và khuy.',1,'4','2026-03-26 13:54:57','2026-03-26 13:54:57'),('06f5e9ee-3489-483c-9aed-b68d8e3a942d','CHÂN VÁY NGẮN PHỒNG DÁNG CÓ CON ĐỈA','Chân váy ngắn cạp vừa. Túi đáp phía trước. Chi tiết con đỉa có khóa kim loại ở cạp và xếp ly. Cài bên cạnh bằng khóa kéo ẩn trong đường may.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('07fad873-427d-4a56-a06f-2f7a04f81917','ÁO KHOÁC DA HIỆU ỨNG CỔ ĐIỂN','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng rộng làm bằng da có hiệu ứng cổ điển. Cổ ve lật và dài tay. Túi đắp có nắp ở hông. Chi tiết túi bên trong. Gấu áo bo gân co giãn. Cài khóa kéo phía trước. <br/><br/>Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-26 13:54:57','2026-03-26 13:54:57'),('0b5b5bd3-2697-4443-8f51-e6a334fb0c0c','ÁO PHÔNG VẢI DỆT CỔ PANADERO','Áo phông dáng relaxed fit. Cổ tròn, cài khuy phía trước. Dài tay. Bo viền.',1,'2','2026-03-26 13:54:57','2026-03-26 13:54:57'),('0e7ab391-bf93-45c4-8d1a-e8ead331e899','QUẦN REGULAR FIT MỎNG NHẸ','Chiều cao người mẫu: 185 cm<br/><br/>Quần dáng regular fit làm từ vải pha cotton và vải lanh chưa qua giặt. Điều này làm cho quần có vẻ ngoài thô cứng trong những lần mặc đầu tiên, nhưng sẽ mềm hơn theo thời gian.<br/><br/>Có túi phía trước và túi phía sau không đối xứng. Cài phía trước bằng khóa kéo và khuy.',1,'4','2026-03-26 13:54:57','2026-03-26 13:54:57'),('0f9fb75c-1e90-4646-ac28-df4cd72f7f1a','ÁO KHOÁC CỔ CAO GẤU CHUN','Áo khoác cổ cao, dài tay. Có hai túi phía trước. Gấu áo bo thun co giãn. Cài khuy phía trước.',1,'5','2026-03-26 13:54:57','2026-03-26 13:54:57'),('0fb7f203-8d78-4567-950e-b7f1fae952b2','JEANS BOOTCUT FIT PHIÊN BẢN GIỚI HẠN','Ống quần đứng từ hông đến mắt cá chân, với phần gấu hơi loe. Cạp lửng. Vải cứng.<br/><br/><br/>Quần jeans ống đứng dáng bootcut làm từ vải denim cotton. Có năm túi. Hiệu ứng bạc màu. Cài khuy phía trước.',1,'4','2026-03-26 13:54:57','2026-03-26 13:54:57'),('1145dfda-2af1-47db-a84a-a35a11e95f56','ĐẦM DỆT KIM NGẮN TAY BỒNG','Đầm mini cổ tròn, tay ngắn bồng.',1,'8','2026-03-26 13:54:58','2026-03-26 13:54:58'),('117ea19d-0531-4abd-8dd9-e54646d52297','ÁO KHOÁC DÁNG RỘNG CHẦN CHỈ NỔI KHÁC MÀU','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng rộng làm từ vải cotton dệt chéo. Cổ ve lật, dài tay, cổ tay bo và cài khuy. Có túi kangaroo phía trước. Toàn thân chần chỉ nổi khác màu. Hiệu ứng phai màu. Cài bằng khóa kéo ở phía trước.',1,'1','2026-03-26 13:54:57','2026-03-26 13:54:57'),('119d1276-0861-43a0-b6e6-4a8a3b63e289','ĐẦM MIDI DENIM TRỄ VAI','Chiều cao người mẫu: 165 cm | Cỡ: XS<br/><br/>Đầm midi cổ ngang, trễ vai. Xếp ly phía trước. Cài khóa kéo kim loại phía sau.',1,'8','2026-03-26 13:54:58','2026-03-26 13:54:58'),('1233396f-5b2e-47a7-80da-b0dbde61c664','ÁO PHÔNG REGULAR FIT PHỐI MÀU COLOR BLOCK','Áo phông dáng regular fit. Cổ tròn bo viền bằng vải gân phối màu tương phản. Tay raglan cộc.',1,'2','2026-03-26 13:54:57','2026-03-26 13:54:57'),('1280b602-fce3-4669-90b0-4917512251e1','CHÂN VÁY MIDI XÒE','Chân váy midi chất liệu cotton 100%. Cạp cao co giãn. Lót trong cùng tông màu.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('1356a685-71b8-4590-bfb0-f1bf45f0777a','ÁO SƠ MI DENIM DÁNG REGULAR FIT','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo sơ mi dáng regular fit, được làm từ vải denim pha sợi cotton và 13% sợi gai dầu. Cổ ve lật, dài tay, cổ tay bo và cài khuy. Có một túi đáp trước ngực. Cài khuy phía trước.<br/><br/>Bộ sưu tập đặc biệt Origins.',1,'3','2026-03-26 13:54:57','2026-03-26 13:54:57'),('1464570a-de84-4977-a5e5-4e8253ed3d31','ĐẦM CỔ YẾM DÁNG BALLOON','Chiều cao người mẫu: 176 cm | Cỡ: S<br/><br/>Đầm ngắn cổ yếm có dây buộc điều chỉnh được. Thắt lưng mảnh cùng chất liệu, có khóa kim loại. Có lớp lót bên trong cùng màu. Gấu dáng balloon. Cài khóa kéo ẩn ở đường may sau lưng.',1,'8','2026-03-26 13:54:58','2026-03-26 13:54:58'),('18c7fc42-4332-4758-b1e4-409ce4a29195','CHÂN VÁY MIDI DỆT KIM MỊN','Chân váy ôm dệt kim mịn, cạp co giãn. Có lớp lót ngắn bên trong.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('1c23a9c4-f4a5-4e06-b024-7fc22ade3d19','ÁO KHOÁC DÁNG THƯỜNG 100% LEN','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng thường làm từ vải len (trừ lớp lót bên trong). Cổ ve lật và dài tay. Túi may viền ở hông. Gấu bo thun co giãn. Cài phía trước bằng khóa kéo. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-26 13:54:57','2026-03-26 13:54:57'),('1e76173d-44ba-4968-b194-14e4cc695cd2','CHÂN VÁY MIDI XÀ RÔNG KHÓA CÀI','Chân váy cạp cao có vạt đắp chéo phía trước và khóa cài. Gấu loe.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('1fc073a3-af93-4080-a5a2-212bea2e9c36','ÁO SƠ MI SỌC TÚI ZW COLLECTION','Chiều cao người mẫu: 179 cm | Cỡ: M<br/><br/>ZARA WOMAN COLLECTION<br/><br/>Áo sơ mi được may bằng sợi viscose. Cổ tròn và tay dài có cổ tay áo. Túi đắp có nắp ở phía trước. Gấu áo bất đối xứng. Cài phía trước bằng khuy cài.',1,'6','2026-03-26 13:54:58','2026-03-26 13:54:58'),('20920c8e-2e6f-4849-a3c5-ee850e01b664','CHÂN VÁY KẺ THÊU NƠ','Chân váy midi cạp cao, thêu họa tiết cùng màu. Dáng xòe. Cài khóa kéo ẩn ở đường may sau lưng.',1,'7','2026-03-26 13:54:58','2026-03-26 13:54:58'),('273bd8fa-7a8b-40c8-983c-c9286833894b','ÁO KHOÁC CỔ CAO DÁNG RỘNG','Chiều cao người mẫu: 177 cm | Cỡ: S<br/><br/>Áo khoác dáng rộng cổ cao có dây rút điều chỉnh. Tay dài, có đai và cài khuy. Có túi chìm ở đường may và túi có nắp, cài khuy phía trước. Cài bằng khóa kéo kim loại phía trước.',1,'5','2026-03-26 13:54:58','2026-03-26 13:54:58'),('2ad9a0bb-4dfc-48a5-b617-246ef0cd3aba','ÁO PHÔNG CỔ POLO KIỂU BÓNG CHÀY','Áo phông dáng suông, chất liệu vải cotton dệt dày. Cổ chữ V, cài khuy bấm phía trước.',1,'2','2026-03-26 13:54:57','2026-03-26 13:54:57'),('3594849a-b185-469d-8ad8-e6bd8789d548','ÁO KHOÁC KỸ THUẬT CHẦN BÔNG CÓ TÚI','Chiều cao người mẫu: 186 cm | Cỡ: L<br/><br/>Áo khoác dáng rộng làm bằng vải kỹ thuật, chần bông bên trong. Cổ cao và dài tay, cổ tay có khuy bấm ẩn. Có túi đáp phía trước có nắp. Có túi bên trong. Cạp quần có dây rút bên trong để điều chỉnh. Cài phía trước bằng khóa kéo ẩn dưới nẹp. Bộ sưu tập đặc biệt Origins.',1,'1','2026-03-26 13:54:57','2026-03-26 13:54:57'),('35a794d6-a223-4664-a938-7223e0f49b5a','ÁO KHOÁC DÁNG RỘNG VẢI CANVAS COTTON','Chiều cao người mẫu: 186 cm | Cỡ: M<br/><br/>Áo khoác dáng rộng làm từ vải cotton dệt canvas. Cổ cao và dài tay, cổ tay cài khuy. Có túi hộp có nắp ở phía trước. Hiệu ứng wash. Cài bằng khóa kéo ẩn dưới nẹp có khóa kéo ở phía trước.',1,'1','2026-03-26 13:54:57','2026-03-26 13:54:57'),('37e7fc3f-a970-46c1-95c6-2236892aa966','ĐẦM DÀI VẢI RŨ','Chiều cao người mẫu: 179 cm | Cỡ: M<br/><br/>Đầm dáng dài làm từ sợi vải pha lyocell. Cổ tròn, tay dài ngang khuỷu tay. Gấu thẳng.',1,'8','2026-03-26 13:54:58','2026-03-26 13:54:58'),('3bf0acc1-3cef-438f-a268-f814e3ca6f30','ÁO KHOÁC GIẢ DA LỘN CÓ DÂY ĐAI','Áo khoác chất liệu giả da lộn. Cổ đứng và dài tay có dây đai ở vai. Túi hộp có nắp phía trước. Cài khóa kéo và khuy bấm ẩn phía trước.',1,'5','2026-03-26 13:54:58','2026-03-26 13:54:58'),('3d024118-4229-4aa8-bcb3-1c7551cdf3e1','ÁO SƠ MI DENIM TAY LOE Z1975','Chiều cao người mẫu: 174 cm<br/><br/>Áo sơ mi cổ ve lật, cổ chữ V, tay loe dưới khuỷu tay. Túi vuông phía trước. Gấu áo không đối xứng. Cài khuy ẩn phía trước.',1,'6','2026-03-26 13:54:58','2026-03-26 13:54:58'),('3e26cac0-b6bc-456c-bca2-4a2b0f613b1f','ÁO SƠ MI DENIM KIỂU MIỀN TÂY','Áo sơ mi dáng rộng làm từ vải denim cotton. Cổ ve lật và tay dài với cổ tay áo cài khuy bấm. Túi đáp có nắp ở ngực. Hiệu ứng bạc màu. Cài khuy bấm phía trước.',1,'3','2026-03-26 13:54:57','2026-03-26 13:54:57'),('40eebc55-5393-4ee0-93c1-85bbc80aa8cb','ÁO RÁP BÈO GẤU LỆCH','Chiều cao người mẫu: 178 cm<br/><br/>Áo cổ tròn, dài tay. Viền ráp bèo. Gấu lệch. Cài bằng khuy bọc vải cùng màu và có xẻ sau lưng.',1,'6','2026-03-26 13:54:58','2026-03-26 13:54:58'),('41f341f7-457f-4912-8fdc-903af1cb12d5','ÁO SƠ MI REGULAR FIT CÓ TÚI ORIGINS','Áo sơ mi dáng regular fit, 